package com.acme.workers

import java.sql.{Connection, PreparedStatement, ResultSet}
import java.util.concurrent.{ExecutorService, Executors, LinkedBlockingQueue}
import javax.sql.DataSource
import com.zaxxer.hikari.{HikariConfig, HikariDataSource}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Domain models
case class NotificationJob(id: Long, userId: Long, templateKey: String, params: Map[String, String])
case class UserPreference(userId: Long, displayName: String, locale: String, htmlEnabled: Boolean)
case class RenderedNotification(jobId: Long, userId: Long, content: String, contentType: String)

// Template registry with pre-approved safe templates
object TemplateRegistry {
  private val templates: Map[String, String] = Map(
    "welcome" -> "<div class='notification'>Welcome, {{displayName}}!</div>",
    "alert" -> "<div class='alert'>{{message}}</div>",
    "digest" -> "<div class='digest'><h2>Daily Digest for {{displayName}}</h2><div>{{summary}}</div></div>",
    "custom" -> "<div class='custom'>{{body}}</div>"
  )

  def getTemplate(key: String): Option[String] = templates.get(key)
}

// HTML encoding utility
object HtmlEncoder {
  def encode(input: String): String = {
    if (input == null) return ""
    input
      .replace("&", "&amp;")
      .replace("<", "&lt;")
      .replace(">", "&gt;")
      .replace("\"", "&quot;")
      .replace("'", "&#x27;")
  }

  // Encodes for safe embedding in HTML attribute context
  def encodeForAttribute(input: String): String = {
    encode(input).replace("/", "&#x2F;")
  }
}

// Content sanitization pipeline
object ContentSanitizer {
  private val allowedTags = Set("b", "i", "em", "strong", "span", "div", "p", "br")
  private val tagPattern = "<(/?)([a-zA-Z]+)([^>]*)>".r

  def sanitizeHtml(content: String): String = {
    tagPattern.replaceAllIn(content, m => {
      val closing = m.group(1)
      val tag = m.group(2).toLowerCase
      if (allowedTags.contains(tag)) {
        s"<$closing$tag>"
      } else {
        HtmlEncoder.encode(m.matched)
      }
    })
  }

  def sanitizeForContext(content: String, htmlEnabled: Boolean): String = {
    if (htmlEnabled) sanitizeHtml(content)
    else HtmlEncoder.encode(content)
  }
}

// Template rendering engine
class TemplateRenderer {
  private val placeholderPattern = "\\{\\{([^}]+)\\}\\}".r

  def render(template: String, params: Map[String, String], userPref: UserPreference): String = {
    placeholderPattern.replaceAllIn(template, m => {
      val key = m.group(1)
      val rawValue = resolveValue(key, params, userPref)
      // Apply context-aware encoding based on user preference
      prepareValue(rawValue, key, userPref)
    })
  }

  private def resolveValue(key: String, params: Map[String, String], pref: UserPreference): String = {
    key match {
      case "displayName" => pref.displayName
      case "locale" => pref.locale
      case other => params.getOrElse(other, "")
    }
  }

  private def prepareValue(value: String, key: String, pref: UserPreference): String = {
    // displayName is considered "trusted" as it comes from user profile DB
    // Other values from job params need sanitization
    key match {
      case "displayName" => value  // Trusted source - user profile
      case _ => ContentSanitizer.sanitizeForContext(value, pref.htmlEnabled)
    }
  }
}

// Connection pool manager
class ConnectionPoolManager {
  private val config = new HikariConfig()
  config.setJdbcUrl(sys.env.getOrElse("DB_URL", "jdbc:postgresql://localhost:5432/notifications"))
  config.setUsername(sys.env.getOrElse("DB_USER", "app"))
  config.setPassword(sys.env.getOrElse("DB_PASS", "secret"))
  config.setMaximumPoolSize(10)
  config.setMinimumIdle(2)
  config.setConnectionTimeout(5000)

  private val dataSource: HikariDataSource = new HikariDataSource(config)

  def getConnection: Connection = dataSource.getConnection
  def shutdown(): Unit = dataSource.close()
}

// User preference repository
class UserPreferenceRepository(pool: ConnectionPoolManager) {
  def findByUserId(userId: Long): Option[UserPreference] = {
    val conn = pool.getConnection
    try {
      val stmt = conn.prepareStatement("SELECT user_id, display_name, locale, html_enabled FROM user_preferences WHERE user_id = ?")
      stmt.setLong(1, userId)
      val rs = stmt.executeQuery()
      if (rs.next()) {
        Some(UserPreference(
          userId = rs.getLong("user_id"),
          displayName = rs.getString("display_name"),
          locale = rs.getString("locale"),
          htmlEnabled = rs.getBoolean("html_enabled")
        ))
      } else None
    } finally {
      conn.close()
    }
  }
}

// Notification output writer
class NotificationWriter(pool: ConnectionPoolManager) {
  def write(notification: RenderedNotification): Unit = {
    val conn = pool.getConnection
    try {
      val stmt = conn.prepareStatement(
        "INSERT INTO rendered_notifications (job_id, user_id, content, content_type) VALUES (?, ?, ?, ?)"
      )
      stmt.setLong(1, notification.jobId)
      stmt.setLong(2, notification.userId)
      stmt.setString(3, notification.content)
      stmt.setString(4, notification.contentType)
      stmt.executeUpdate()
    } finally {
      conn.close()
    }
  }
}

// Background job worker
class NotificationWorker(poolManager: ConnectionPoolManager) {
  private val renderer = new TemplateRenderer()
  private val userRepo = new UserPreferenceRepository(poolManager)
  private val writer = new NotificationWriter(poolManager)
  private val jobQueue = new LinkedBlockingQueue[NotificationJob](1000)
  private val executor: ExecutorService = Executors.newFixedThreadPool(4)

  def enqueue(job: NotificationJob): Boolean = jobQueue.offer(job)

  def start(): Unit = {
    for (_ <- 1 to 4) {
      executor.submit(new Runnable {
        override def run(): Unit = processLoop()
      })
    }
  }

  private def processLoop(): Unit = {
    while (!Thread.currentThread().isInterrupted) {
      Try(jobQueue.take()) match {
        case Success(job) => processJob(job)
        case Failure(_) => // interrupted
      }
    }
  }

  private def processJob(job: NotificationJob): Unit = {
    val userPref = userRepo.findByUserId(job.userId).getOrElse {
      UserPreference(job.userId, "User", "en", htmlEnabled = false)
    }

    val templateOpt = TemplateRegistry.getTemplate(job.templateKey)
    templateOpt.foreach { template =>
      val content = renderer.render(template, job.params, userPref)
      val contentType = if (userPref.htmlEnabled) "text/html" else "text/plain"
      writer.write(RenderedNotification(job.id, job.userId, content, contentType))
    }
  }

  def shutdown(): Unit = {
    executor.shutdownNow()
    poolManager.shutdown()
  }
}
